export function roundMoney(x) {
  return Math.round(x * 100) / 100
}

export function orderTotal(items, taxRate = 0) {
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0)
  return roundMoney(subtotal * (1 + taxRate))
}

